const email = $input.item.json;

function stripHtml(html) { 
  return html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function stripHistory(text) { 
  return text.split(/(?:Le |On |From:)/)[0].trim();
}

function stripSignature(text) { 
  return text.split(/(?:Cordialement|Bien cordialement|Cdlt)/i)[0].trim();
}

function cleanup(text) { 
  return text.replace(/\s+/g, ' ').trim();
}

let raw = email.text || email.html || "";
if (email.html && !email.text) { 
  raw = stripHtml(email.html); 
}

let cleaned = stripHistory(raw);
cleaned = stripSignature(cleaned);
cleaned = cleanup(cleaned);

return {
  json: {
    id: email.messageId || email.id || "",
    subject: email.subject || "",
    threadId: email.threadId || "",
    internalDate: email.internalDate || "",
    titre: email.subject || "",
    email_complet: cleaned || "",
    expediteur: email.from?.value?.[0]?.name || "",
    dateenvoi : $json.date || "",
  }
};

const items = $input.all();

// Grouper par threadId
const threads = {};
items.forEach(item => {
  const tid = item.json.threadId;
  if (!threads[tid]) {
    threads[tid] = {
      threadId: tid,
      emails: []
    };
  }
  threads[tid].emails.push(item.json);
});

// Retourner un item par thread
return Object.values(threads).map(thread => ({
  json: thread
}));

const validatorInputs = $input.all();
const mergeOutputs = $('Parser du merge').all();

return validatorInputs.map((item, index) => {
  let text = item.json.output;

  // Parser la validation
  text = text.replace(/```json/g, '');
  text = text.replace(/```/g, '');
  text = text.replace(/\n/g, '');
  text = text.trim();

  const start = text.indexOf('{');
  const end = text.lastIndexOf('}') + 1;
  const jsonStr = text.substring(start, end);
  const validation = JSON.parse(jsonStr);

  // Récupère les données correspondantes du merge
  const dataOriginal = mergeOutputs[index].json;

  return {
    json: {
      // Garde TOUTES les données originales
      threadId: dataOriginal.threadId,
      emails: dataOriginal.emails,
      emails_texte_complet: dataOriginal.emails_texte_complet,
      summary_texte: dataOriginal.summary_texte,
      summary_json: dataOriginal.summary_json,
      resume_seul: dataOriginal.resume_seul,
      // Ajoute la validation
      validation: validation.validation,
      score_fidelite: validation.score_fidelite,
      erreurs_critiques: validation.erreurs_critiques,
      suggestions: validation.suggestions
    }
  };
});

