const items = $input.all();

return items.map(item => {
  const data = item.json;

  // Fusionner tous les contenus d'emails
  const emailsFusionnes = data.emails.map((email, index) => {
    return `
Email ${index + 1} - ${email.expediteur} (${new Date(email.dateenvoi).toLocaleDateString('fr-FR')})
Sujet: ${email.subject}

${email.email_complet}
`;
  }).join('\n---\n');

  // Créer le texte du résumé au format lisible
  const summaryTexte = `
Titre: ${data.titre}

Problème: ${data.probleme}

État: ${data.etat}

Action suivante: ${data.action_suivante}

Montants: ${data.montants.length > 0 ? JSON.stringify(data.montants, null, 2) : 'Aucun'}

Entreprises: ${data.entreprises.join(', ') || 'Aucune'}

Documents: ${data.documents.join(', ') || 'Aucun'}

Blocage: ${data.blocage || 'Aucun'}
`.trim();

  return {
    json: {
      threadId: data.threadId,
      emails: data.emails,
      emails_texte_complet: emailsFusionnes,
      summary_texte: summaryTexte, // Version texte pour le prompt
      summary_json: data, // Version JSON complète
      resume_seul: summaryTexte
    }
  };
});

const data = $input.all();

// Récupérer la date du jour
const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
const dateAujourdhui = new Date().toLocaleDateString('fr-FR', options);

// Compter le nombre de fils de discussion
const nbThreads = data.length;

// Début du HTML avec titre global
let htmlComplet = `<div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto;">
  <h1 style="color: #0066cc;">Rapport syndic - ${dateAujourdhui}</h1>
  <p style="font-size: 16px; color: #666;">${nbThreads} fil(s) de discussion</p>
  <hr style="border: 1px solid #ddd; margin: 20px 0;">`;

// Parcourir chaque email
data.forEach(item => {
  let parsed;
  const output = item.json.output;

  // Nettoyer le JSON si besoin (enlever les backticks markdown)
  const cleanOutput = output.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

  try {
    parsed = JSON.parse(cleanOutput);
  } catch (e) {
    console.error('Erreur parsing:', e);
    return;
  }

  const titre = parsed.Titre || parsed.titre || '';
  const probleme = parsed.Problème || parsed.problème || '';
  const etat = parsed.État || parsed.état || '';
  const action = parsed['Action suivante'] || parsed.action_suivante || '';
  const montants = parsed.Montants || parsed.montants || [];
  const entreprises = parsed.Entreprises || parsed.entreprises || [];
  const documents = parsed.Documents || parsed.documents || [];
  const blocage = parsed.Blocage || parsed.blocage || '';

  let badgeColor = '#999';
  if (etat.toLowerCase().includes('cours')) badgeColor = '#ff9800';
  if (etat.toLowerCase().includes('résolu')) badgeColor = '#4caf50';

  htmlComplet += `
  <div style="margin: 30px 0; padding: 20px; background: #f9f9f9; border-left: 4px solid #0066cc;">
    <h2 style="color: #333; margin: 0 0 10px 0;">${titre}</h2>
    <p style="margin: 10px 0;">
      <span style="display: inline-block; padding: 4px 12px; background: ${badgeColor}; color: white; border-radius: 4px; font-size: 12px; font-weight: bold;">
        ${etat.toUpperCase()}
      </span>
    </p>`;

  if (probleme) {
    htmlComplet += `<p style="color: #555; line-height: 1.6;">${probleme}</p>`;
  }

  if (action) {
    htmlComplet += `<p style="margin: 15px 0; padding: 10px; background: #fff3cd; border-left: 3px solid #ffc107;">
      <strong>🎯 Action :</strong> ${action}
    </p>`;
  }

  if (montants && montants !== 'Aucun') {
    if (Array.isArray(montants)) {
      montants.forEach(m => {
        htmlComplet += `<p style="margin: 10px 0;"><strong>💰 Montants :</strong> ${m.montant} (${m.contexte})</p>`;
      });
    } else {
      htmlComplet += `<p style="margin: 10px 0;"><strong>💰 Montants :</strong> ${montants}</p>`;
    }
  }

  if (entreprises && entreprises !== 'Aucune') {
    const listeEntreprises = Array.isArray(entreprises) ? entreprises.join(', ') : entreprises;
    htmlComplet += `<p style="margin: 10px 0;"><strong>🏢 Entreprises :</strong> ${listeEntreprises}</p>`;
  }

  if (documents && documents !== 'Aucun') {
    const listeDocs = Array.isArray(documents) ? documents.join(', ') : documents;
    htmlComplet += `<p style="margin: 10px 0;"><strong>📄 Documents :</strong> ${listeDocs}</p>`;
  }

  if (blocage && blocage !== 'Aucun') {
    htmlComplet += `<p style="margin: 15px 0; padding: 10px; background: #ffebee; border-left: 3px solid #f44336; color: #c62828;">
      <strong>⚠️ Blocage :</strong> ${blocage}
    </p>`;
  }

  htmlComplet += `</div>`;
});

htmlComplet += `
  <hr style="border: 1px solid #ddd; margin: 30px 0;">
  <p style="color: #999; font-size: 12px; text-align: center;">Rapport généré automatiquement</p>
</div>`;

return [{
  json: {
    titre: `Rapport syndic - ${dateAujourdhui}`,
    html: htmlComplet,
    nb_threads: nbThreads
  }
}];

